import urllib.request, json
repos=['h5py','numpy','python']
for repo in repos:
 print('REPO', repo)
 try:
  data=json.load(urllib.request.urlopen(f'https://quay.io/api/v1/repository/biocontainers/{repo}/tag/?limit=100&page=1&onlyActiveTags=true',timeout=20))
  for t in data.get('tags',[])[:20]: print(t.get('name'))
 except Exception as e: print('ERR',e)
PY"

