/bin/bash -lc "python - <<'PY'
# Local extraction/consistency check from Galaxy count outputs and staged metadata.
from collections import defaultdict
# tumor samples in the order generated by sorting SampleID, matching h5ad Patient_### counts
rows=[]
with open('meta.csv', newline='') as f:
    import csv
    r=csv.DictReader(f)
    per=defaultdict(lambda: defaultdict(int)); disease={}
    for row in r:
        if row['Tissue']"'!='"'Tumor':
            continue
        sid=row['SampleID']; per[sid][row['CellName']]+=1; disease[sid]=row['Disease']
for i,sid in enumerate(sorted(per), start=1):
    total=sum(per[sid].values())
    patient=f'Patient_{i:03d}'
    if patient in {'Patient_005','Patient_006','Patient_007','Patient_018','Patient_040'}:
        print(patient, sid, disease[sid], total, 'DC', per[sid].get('DC',0), 'prop', per[sid].get('DC',0)/total)
